contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit an arbitrary amount into c and assert observable invariants when Deposit does NOT revert.
    // amount: how much Ether to send with Deposit. The test contract must hold at least `amount`.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // Read before-values
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Perform Deposit, capture whether it reverted
        bool reverted;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // If Deposit returned (did not revert), then recorded balance increased by exactly amount
        // and the contract's Ether balance increased by exactly amount.
        assert(reverted || (afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount));
    }

    // allow receiving Ether from Collect if needed in other tests
    receive() external payable { }
}

